const EW=330,EH=200,ESC=2,ELIVE={};
const isAn=c=>!!c&&c.tier>=2,ek=c=>c.tier*10+c.kind;
function epicLive(k){if(k<20)k+=20;let L=ELIVE[k];if(L)return L;const tl=(k>=50?RICH:k>=40?TOI:k>=30?LEG:EPIC)[k%10],cv=document.createElement('canvas');cv.width=EW*ESC;cv.height=EH*ESC;const ctx=cv.getContext('2d');ctx.scale(ESC,ESC);
  const off=document.createElement('canvas');off.width=EW*ESC;off.height=EH*ESC;const oc=off.getContext('2d');oc.scale(ESC,ESC);const st={};
  const M=s=>function(){s|=0;s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296};
  try{const i=k%10;tl.bg(oc,M(k>=50?i*2311+101:k>=40?i*1231+77:i*977+(k>=30?31:13)),st)}catch(e){console.error(e)}L=ELIVE[k]={cv,ctx,off,st,tl,last:-1};epicDraw(k,1.5);return L}
function epicDraw(k,t){const L=ELIVE[k]||epicLive(k),c=L.ctx;try{c.save();c.globalAlpha=1;c.setLineDash([]);c.lineCap='butt';c.drawImage(L.off,0,0,EW,EH);L.tl.d(c,t,L.st);c.restore()}catch(e){}L.last=performance.now();return L.cv}
function epicTick(k){const L=epicLive(k);if(performance.now()-L.last>55)epicDraw(k,performance.now()/1000);return L.cv}
/* vẽ phủ kín khung (giữ tỉ lệ, cắt bớt mép) */
function cover(q,src,dx,dy,dw,dh){const sw=src.width,sh=src.height,r=Math.max(dw/sw,dh/sh),w=dw/r,h=dh/r;q.drawImage(src,(sw-w)/2,(sh-h)/2,w,h,dx,dy,dw,dh)}
const THUMB={};function thumb(c){if(THUMB[c.id])return THUMB[c.id];const cv=document.createElement('canvas');cv.width=cv.height=128;const q=cv.getContext('2d');if(isAn(c))cover(q,epicLive(ek(c)).cv,0,0,128,128);else q.drawImage(tile(c),0,0,256,256,0,0,128,128);return THUMB[c.id]=cv.toDataURL('image/png')}
