/* ---------- hiển thị thảm: sảnh Trụ sở, trận 2D, trận 3D ---------- */
function paintBase(){try{const bd=document.getElementById('bboard'),p=bd&&bd.querySelector('.bplay');if(!p)return;const c=cur();let m=bd.querySelector('.c39mat');
  if(c.id==='cp0'){if(m)m.remove();return}
  if(!m){m=document.createElement('div');m.className='c39mat';m.style.cssText='position:absolute;pointer-events:none;z-index:0;opacity:.9';bd.insertBefore(m,bd.firstChild)}
  ['left','top','width','height'].forEach(k=>m.style[k]=p.style[k]);if(isAn(c)){if(m.dataset.cp!==c.id){m.dataset.cp=c.id;m.style.backgroundImage='';m.innerHTML='<canvas style="width:100%;height:100%;display:block"></canvas>'}return}else if(m.firstChild)m.innerHTML='';if(m.dataset.cp!==c.id){m.dataset.cp=c.id;m.style.backgroundImage=`linear-gradient(rgba(0,0,0,.2),rgba(0,0,0,.2)),url(${thumb(c)})`;m.style.backgroundSize='auto,calc(var(--c)*4) calc(var(--c)*4)'}}catch(e){}}
if(typeof bRender==='function'){const _b=bRender;bRender=function(){const r=_b.apply(this,arguments);paintBase();return r}}
C39.pat2=function(q,s,bx,by){const c=cur();if(c.id==='cp0'||isAn(c))return null;try{const pt=q.createPattern(tile(c),'repeat'),k=s*4/256;if(pt.setTransform)pt.setTransform(new DOMMatrix([k,0,0,k,bx,by]));return pt}catch(e){return null}};
